    [IO.Directory]::CreateDirectory($Root)|Out-Null;$captureRoot=Join-Path $Root 'captures';[IO.Directory]::CreateDirectory($captureRoot)|Out-Null;$culture=if($AppLanguage-ceq'Thai'){'th-TH'}else{'en-US'};$s1='1'*64;$s2='2'*64;$s3='3'*64;$s4='4'*64
